+  s1 = u8"bügeln";
+  s2 = u8"braten";
+  s1ba = ByteArrayFromString(s1);
+  s2ba = ByteArrayFromString(s2);
+  ASSERT_TRUE(comparator->Compare(s1ba, s2ba));
+}
+
