+
+    String line = fileReader.readLine();
+    String lastLine = null;
+
+    assertEquals("-----BEGIN CERTIFICATE-----", line);
+    while (line != null) {
+      lastLine = line;
+      line = fileReader.readLine();
+    }
+
+    assertEquals("-----END CERTIFICATE-----", lastLine);
+  }
+
