+        IgniteEx node1 = node(NODE_1)
+            .andCache(CACHE_1)
+            .start();
+
+        IgniteEx node2 = node(NODE_2)
+            .withDefaultRegion("defaultName2", MEMORY)
+            .andCache(CACHE_2)
+            .start();
+
+        node1.cluster().active(true);
+
+        populateCache(node1, CACHE_1, 1000);
