+  Status collect_field_names(const arrow::StructType* type) {
+    const auto nf = type->num_children();
+    field_names_.reserve(nf);
+    (void)rb::protect([&]{
+      for (int i = 0; i < nf; ++i) {
+        auto field = type->child(i);
+        auto& name = field->name();
