+using FlatBuffers;
+using System;
+using System.Buffers.Binary;
+using System.IO;
+using System.Linq;
+using System.Threading;
+using System.Threading.Tasks;
+
+namespace Apache.Arrow.Ipc
+{
+    internal class ArrowFileReaderImplementation : ArrowStreamReaderImplementation
+    {
+        public bool IsFileValid { get; private set; }
+
+        /// <summary>
+        /// When using GetNextRecordBatch this value 
+        /// is to remember what index is next
+        /// </summary>
+        private int _recordBatchIndex;
+
+        /// <summary>
+        /// Notes what byte position where the footer data is in the stream
+        /// </summary>
+        private int _footerStartPostion;
+
+        private ArrowFooter _footer;
+
+        public ArrowFileReaderImplementation(Stream stream) : base(stream)
+        {
+        }
+
+        public async Task<int> RecordBatchCountAsync()
+        {
+            if (!HasReadSchema)
+            {
+                await ReadSchemaAsync();
+            }
+
+            return _footer.RecordBatchCount;
+        }
+
+        protected override async Task ReadSchemaAsync()
+        {
+            if (HasReadSchema)
+            {
+                return;
+            }
+
+            await ValidateFileAsync();
+
+            var bytesRead = 0;
+            var footerLength = 0;
+
+            await Buffers.RentReturnAsync(4, async (buffer) =>
+            {
+                BaseStream.Position = BaseStream.Length - ArrowFileConstants.Magic.Length - 4;
+
+                bytesRead = await BaseStream.ReadAsync(buffer, 0, 4);

 Review comment:
   Ideally this would wrap the `byte[]` into a `Memory<byte>` in order to use the newer `ReadAsync` overload on `Stream`.  The reason for that is that newer overload returns a `ValueTask<int>` rather than ` Task<int>`, which has two benefits:
   1) It allows for the stream to avoid allocating a `Task<int>` object just to return the `Int32` value when the operation completes synchronously.  Most stream implementations will benefit from this, including `FileStream`.
   2) It allows for the stream implementation to pool an object that backs the `ValueTask<int>` and thus have amortized-zero-allocation even for asynchronously completing operations.  `NetworkStream`, for example, does this.

