+                            ) {
+                                Ok((count, _)) => {
+                                    let mut builder = Int64Builder::new(count);
+
+                                    for i in 0..count {
+                                        let v = read_buffer[i].data();
+                                        let value: u128 = (v[0] as u128) << 64
