+                                    let mut builder = Int64Builder::new(count);
+
+                                    for i in 0..count {
+                                        let v = read_buffer[i].data();
+                                        let value: u128 = (v[0] as u128) << 64
+                                            | (v[1] as u128) << 32
+                                            | (v[2] as u128);
+                                        let ms: i64 = (value / 1000000) as i64;
+                                        builder.append_value(ms).unwrap();
+                                    }
