+pub struct ParquetTable {
+    filename: String,
+    schema: Arc<Schema>,
+}
+
+impl ParquetTable {
+    pub fn try_new(filename: &str) -> Result<Self> {
+        let file = File::open(filename)?;
+        let parquet_file = ParquetFile::open(file, None)?;
+        let schema = parquet_file.projection_schema.clone();
