+macro_rules! read_binary_column {
+    ($SELF:ident, $R:ident, $INDEX:expr) => {{
+        let mut read_buffer: Vec<ByteArray> =
+            vec![ByteArray::default(); $SELF.batch_size];
+        let mut def_levels: Vec<i16> = vec![0; $SELF.batch_size];
